const wh = $input.first().json;
const body = wh.body || wh;
const leadId = body.lead_id || body.odoo_lead_id;
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
let lead = {};
try {
  lead = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://intellixcrm.com/api/haidly/lead/${leadId}`,
    headers: { 'X-Haidly-Webhook-Token': token },
    json: true,
  });
} catch (e) {}
return [{ json: { ...body, ...lead, lead_id: leadId } }];

const body = $input.first().json;
const { total_call_attempts = 0, haidly_do_not_call, do_not_call } = body;
if (do_not_call || haidly_do_not_call) {
  return [{ json: { ...body, action: 'STOP_ALL_CONTACT' } }];
}
const maxDay = 3;
const maxTotal = 10;
if (total_call_attempts >= maxTotal || (body.haidly_total_call_attempts || 0) >= maxTotal) {
  return [{ json: { ...body, action: 'ARCHIVE' } }];
}
const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const h = new Date(nowStr).getHours();
const day = new Date(nowStr).getDay();
if (day === 0 || h < 9 || h >= 19) {
  return [{ json: { ...body, action: 'WAIT', reason: 'outside_hours' } }];
}
return [{ json: { ...body, action: 'PROCEED_TO_CALL' } }];

const body = $input.first().json;
const rn = parseInt(body.relance_number || 1, 10);
const icpAgents = body.relance_agents || {};
const map = {
  1: icpAgents.j1,
  2: icpAgents.j3,
  3: icpAgents.j7,
  4: icpAgents.j14,
};
const agentId = map[rn] || body.agent_id || '';
const first = (body.first_name || body.lead_name || 'there').split(' ')[0];
return [{ json: {
  ...body,
  agent_id: agentId,
  agent_phone_number_id: body.elevenlabs_phone_number_id || '',
  dynamic_variables: {
    lead_name: first,
    project_type: body.project_type || 'multi',
    city: body.city || '',
    budget_range: body.budget_range || '',
    property_type: body.property_type || '',
    lead_id_odoo: String(body.lead_id || '')
  }
}}];

const j = $input.first().json;
const apiKey = '{{ELEVENLABS_API_KEY}}';
if (!j.agent_id || !j.agent_phone_number_id || !j.phone) {
  return [{ json: { ...j, error: 'missing_ids' } }];
}
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
  headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
  body: {
    agent_id: j.agent_id,
    agent_phone_number_id: j.agent_phone_number_id,
    to_number: j.phone,
    telephony_call_config: { ringing_timeout_secs: 25 },
    conversation_initiation_client_data: { dynamic_variables: j.dynamic_variables }
  },
  json: true,
});
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/haidly/lead/update',
  headers: { 'X-Haidly-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: { lead_id: parseInt(j.lead_id, 10), increment_call_attempt: true, conversation_id: res.conversation_id || '' },
  json: true,
});
return [{ json: { ...j, ...res } }];
